"""Threshold rule: stateful per-IP sliding window (brute force, scanning, ...).

Fires one finding per burst that crosses the configured threshold.
See docs/engine-plan.md §6.
"""

from __future__ import annotations

from collections import deque
from collections.abc import Iterable
from datetime import datetime, timedelta

from constants import DEFAULT_MAX_EVIDENCE
from engine.rules.base import Rule
from engine.rules.registry import register
from engine.rules.utils import FieldExtractor, Predicate, add_evidence, resolve_preset
from models import AuthLogEntry, AuthOutcome, Finding, LogEntry, Severity, WebLogEntry
from utils.exceptions import RuleConfigError

# Named predicates (the config-safe "match" presets).


def _auth_failure(entry: LogEntry) -> bool:
    return isinstance(entry, AuthLogEntry) and entry.outcome in (AuthOutcome.FAILURE, AuthOutcome.INVALID_USER)


def _web_login_failure(entry: LogEntry) -> bool:
    # A failed request (401/403) to a login-shaped endpoint — deliberately
    # narrower than "any 401/403", which would also catch admin-path probing
    # (a different signal, not login brute force).
    if not isinstance(entry, WebLogEntry) or entry.status not in (401, 403):
        return False
    path = entry.path
    return path is not None and "login" in path.lower()


def _web_404(entry: LogEntry) -> bool:
    return isinstance(entry, WebLogEntry) and entry.status == 404


MATCH_PREDICATES: dict[str, Predicate] = {
    "auth_failure": _auth_failure,
    "web_login_failure": _web_login_failure,
    "web_404": _web_404,
}


# Named field extractors for `distinct_by` — also a config-safe preset set.


def _distinct_path(entry: LogEntry) -> str | None:
    """Normalized path key: no query, trailing slash trimmed (except root)."""
    if not isinstance(entry, WebLogEntry) or entry.path is None:
        return None
    path = entry.path
    if len(path) > 1:
        path = path.rstrip("/") or "/"
    return path


def _distinct_username(entry: LogEntry) -> str | None:
    return entry.username if isinstance(entry, AuthLogEntry) else None


DISTINCT_EXTRACTORS: dict[str, FieldExtractor] = {
    "path": _distinct_path,
    "username": _distinct_username,
}


@register("threshold")
class ThresholdRule(Rule):
    """Per-IP sliding window; fires one finding per burst that crosses threshold."""

    def __init__(
        self,
        *,
        id: str,
        match: str,
        threshold: int,
        window_seconds: float,
        severity: Severity = Severity.MEDIUM,
        distinct_by: str | None = None,
        title: str | None = None,
        description: str = "",
        max_evidence: int = DEFAULT_MAX_EVIDENCE,
    ) -> None:
        if threshold < 1:
            raise RuleConfigError(f"threshold must be >= 1, got {threshold!r}")
        if window_seconds <= 0:
            raise RuleConfigError(f"window_seconds must be > 0, got {window_seconds!r}")
        self.id = id
        self.title = title or id
        self.severity = severity
        self.description = description
        self.threshold = threshold
        self.window = timedelta(seconds=window_seconds)
        self.max_evidence = max_evidence
        self._match_name = match
        self._match = resolve_preset(match, MATCH_PREDICATES, "match preset")
        self._distinct_name = distinct_by
        self._distinct = resolve_preset(distinct_by, DISTINCT_EXTRACTORS, "distinct_by field") if distinct_by else None
        # Per-IP window state.
        self._events: dict[str | None, deque[LogEntry]] = {}
        self._active: dict[str | None, Finding] = {}
        self._max_seen: dict[str | None, datetime] = {}

    def reset(self) -> None:
        self._events = {}
        self._active = {}
        self._max_seen = {}

    def inspect(self, entry: LogEntry) -> Iterable[Finding]:
        if not self._match(entry):
            return ()

        ip = entry.source_ip
        window = self._events.setdefault(ip, deque())
        window.append(entry)

        # Evict events older than `window` relative to the right edge, which is
        # the max timestamp seen for this IP so far — not necessarily this
        # entry's own timestamp, since a single IP's events aren't guaranteed
        # to arrive in order (§6.3 out-of-order tolerance).
        right_edge = self._max_seen.get(ip)
        if right_edge is None or entry.timestamp > right_edge:
            right_edge = entry.timestamp
        self._max_seen[ip] = right_edge
        cutoff = right_edge - self.window
        while window and window[0].timestamp < cutoff:
            window.popleft()

        count = self._count(window)
        if count < self.threshold:
            # Burst has subsided (or not yet begun): clear any active finding so
            # a later crossing starts a fresh one — one finding per burst.
            self._active.pop(ip, None)
            return ()

        emitted = self._update_finding(ip, window, count, entry)
        return (emitted,) if emitted is not None else ()

    def _count(self, window: deque[LogEntry]) -> int:
        if self._distinct is None:
            return len(window)
        values = {self._distinct(e) for e in window}
        values.discard(None)
        return len(values)

    def _update_finding(self, ip: str | None, window: deque[LogEntry], count: int, entry: LogEntry) -> Finding | None:
        finding = self._active.get(ip)
        newly_emitted = finding is None
        if finding is None:
            finding = Finding(
                rule_id=self.id,
                title=self.title,
                severity=self.severity,
                description=self.description,
                first_seen=window[0].timestamp,
                last_seen=entry.timestamp,
                source_ip=ip,
                count=count,
                sources={entry.source},
                evidence=[],
                metadata={
                    "match": self._match_name,
                    "distinct_by": self._distinct_name,
                    "threshold": self.threshold,
                    "window_seconds": self.window.total_seconds(),
                },
            )
            self._active[ip] = finding

        finding.count = count
        finding.last_seen = max(finding.last_seen, entry.timestamp)
        finding.sources.add(entry.source)
        add_evidence(finding, entry, self.max_evidence)

        return finding if newly_emitted else None

    def flush(self) -> Iterable[Finding]:
        # Findings are emitted eagerly on the crossing event; nothing buffered.
        return ()

"""Cross-rule correlation.

Groups findings by IP and clusters those close in time into ``Incident``s. An
incident forms only for genuine multi-signal activity (≥2 distinct rules OR ≥2
sources for the same IP) — a single rule's repeated findings never do.

See docs/engine-plan.md §7.
"""

from __future__ import annotations

from collections import defaultdict
from collections.abc import Iterable
from datetime import datetime, timedelta
import hashlib

from constants import DEFAULT_CORRELATION_WINDOW_MINUTES
from models import Finding, Incident, Severity


class Correlator:
    """Stateless correlator; clusters findings per IP within a time window."""

    def __init__(self, window: timedelta = timedelta(minutes=DEFAULT_CORRELATION_WINDOW_MINUTES)) -> None:
        self.window = window

    def correlate(self, findings: Iterable[Finding]) -> list[Incident]:
        by_ip: dict[str | None, list[Finding]] = defaultdict(list)
        for f in findings:
            by_ip[f.source_ip].append(f)

        incidents: list[Incident] = []
        for ip, ip_findings in by_ip.items():
            if ip is None:
                continue  # can't meaningfully correlate findings with no IP
            ip_findings.sort(key=lambda f: f.first_seen)
            for cluster in self._cluster(ip_findings):
                incident = self._build_incident(ip, cluster)
                if incident is not None:
                    incidents.append(incident)

        incidents.sort(key=lambda i: (i.first_seen, i.source_ip or ""))
        return incidents

    def _cluster(self, findings: list[Finding]) -> list[list[Finding]]:
        """Greedily group findings whose gap from the running span <= window."""
        clusters: list[list[Finding]] = []
        current: list[Finding] = []
        current_end: datetime | None = None
        for f in findings:
            if current_end is not None and f.first_seen - current_end <= self.window:
                current.append(f)
                current_end = max(current_end, f.last_seen)
            else:
                if current:
                    clusters.append(current)
                current = [f]
                current_end = f.last_seen
        if current:
            clusters.append(current)
        return clusters

    def _build_incident(self, ip: str, cluster: list[Finding]) -> Incident | None:
        rule_ids = {f.rule_id for f in cluster}
        sources = {s for f in cluster for s in f.sources}
        if len(rule_ids) < 2 and len(sources) < 2:
            return None

        first_seen = min(f.first_seen for f in cluster)
        last_seen = max(f.last_seen for f in cluster)
        severity = self._escalate(max(f.severity for f in cluster))

        # sha1 for a short deterministic display id, not a security use of the hash.
        incident_id = (
            "INC-"
            + hashlib.sha1(  # noqa: S324
                (f"{ip}|{first_seen.isoformat()}|" + ",".join(sorted(rule_ids))).encode()
            ).hexdigest()[:10]
        )

        return Incident(
            incident_id=incident_id,
            title=f"Correlated activity from {ip}",
            severity=severity,
            source_ip=ip,
            first_seen=first_seen,
            last_seen=last_seen,
            findings=list(cluster),
            narrative=self._narrative(ip, cluster, rule_ids, sources, first_seen, last_seen),
        )

    @staticmethod
    def _escalate(max_severity: Severity) -> Severity:
        """One level above the max child severity, capped at CRITICAL."""
        members = sorted(Severity)
        idx = members.index(max_severity)
        return members[min(idx + 1, len(members) - 1)]

    @staticmethod
    def _narrative(
        ip: str,
        cluster: list[Finding],
        rule_ids: set[str],
        sources: set[str],
        first_seen: datetime,
        last_seen: datetime,
    ) -> str:
        span = last_seen - first_seen
        titles = sorted({f.title for f in cluster})
        return (
            f"{ip} triggered {len(cluster)} findings across {len(rule_ids)} rule(s) "
            f"({', '.join(titles)}) over {', '.join(sorted(sources))} "
            f"within {span} ({first_seen.isoformat()} → {last_seen.isoformat()})."
        )

"""Pydantic validation for CLI-supplied log file arguments.

Kept separate from the top-level ``models`` package (which is the engine's
data-model surface) to avoid ``from models import X`` / ``from cli.models
import Y`` ambiguity in the same file.
"""

from __future__ import annotations

from pathlib import Path
from typing import Annotated

from pydantic import AfterValidator, BaseModel, ValidationError, model_validator

from utils.exceptions import CliInputError


def _check_log_file(path: Path) -> Path:
    if not path.exists():
        raise ValueError(f"{path}: no such file")
    if not path.is_file():
        raise ValueError(f"{path}: not a regular file")
    if path.suffix.lower() != ".log":
        raise ValueError(f"{path}: expected a '.log' file, got {path.suffix or '(no extension)'}")
    return path


_LogFilePath = Annotated[Path, AfterValidator(_check_log_file)]


class LogFileArgs(BaseModel):
    """Validated set of CLI-supplied log file paths."""

    paths: list[_LogFilePath]

    @model_validator(mode="after")
    def _check_non_empty_and_unique(self) -> LogFileArgs:
        if not self.paths:
            raise ValueError("at least one log file is required")
        resolved = [p.resolve() for p in self.paths]
        seen: set[Path] = set()
        dupes: set[Path] = set()
        for p in resolved:
            (dupes if p in seen else seen).add(p)
        if dupes:
            names = ", ".join(str(d) for d in sorted(dupes))
            raise ValueError(f"duplicate log file path(s): {names}")
        return self


def validate_log_files(paths: list[Path]) -> list[Path]:
    """Validate CLI-supplied paths, raising ``CliInputError`` (never pydantic's own type)."""
    try:
        return LogFileArgs(paths=paths).paths
    except ValidationError as exc:
        messages = [err["msg"].removeprefix("Value error, ") for err in exc.errors()]
        raise CliInputError("; ".join(messages)) from exc

"""Factory that turns structured config specs into ``Rule`` instances."""

from __future__ import annotations

from collections.abc import Iterable
from typing import Any

from engine.rules.base import Rule
from engine.rules.registry import RULE_TYPES
from models import Severity
from utils.exceptions import RuleConfigError


def build_rules(specs: Iterable[dict[str, Any]]) -> list[Rule]:
    """Instantiate rules from structured specs (list of dicts).

    Each spec: ``{id, type, enabled?, severity?, params?}``. ``severity`` (top
    level) and everything in ``params`` are merged into the rule constructor.
    Disabled specs are skipped. Format loading (YAML/TOML) lives outside core.
    """
    rules: list[Rule] = []
    for spec in specs:
        if not spec.get("enabled", True):
            continue
        if "id" not in spec:
            raise RuleConfigError(f"rule spec missing required 'id' field: {spec!r}")
        rule_id = spec["id"]
        type_name = spec.get("type")
        if type_name not in RULE_TYPES:
            raise RuleConfigError(f"unknown rule type {type_name!r} for id {rule_id!r}")
        cls = RULE_TYPES[type_name]

        try:
            kwargs: dict[str, Any] = {"id": rule_id}
            if "severity" in spec:
                kwargs["severity"] = _coerce_severity(spec["severity"])
            for key, value in spec.get("params", {}).items():
                kwargs[key] = _coerce_severity(value) if key == "severity" else value
            rules.append(cls(**kwargs))
        except Exception as e:
            raise RuleConfigError(f"failed to build rule {rule_id!r} (type={type_name!r}): {e}") from e
    return rules


def _coerce_severity(value: Any) -> Severity:  # noqa: ANN401 (genuinely dynamic: parsed config data)
    if isinstance(value, Severity):
        return value
    if isinstance(value, str):
        return Severity.from_name(value)
    return Severity(value)

